choose.when:
WITH grouped AS (
    SELECT peer_id AS name, SUM(ban_count)::bigint AS value
    FROM dashboard_ban_daily_peer
    WHERE bucket >= #{startAt} AND bucket < #{endAt}
    GROUP BY peer_id
)
SELECT name, value, SUM(value) OVER () AS total
FROM grouped
ORDER BY value DESC, name
LIMIT #{limit}

WITH grouped AS (
    SELECT COALESCE(NULLIF(peer_id, ''), 'Unknown') AS name, COUNT(*)::bigint AS value
    FROM ban_history
    WHERE populate_time >= #{startAt} AND populate_time < #{endAt}
    GROUP BY COALESCE(NULLIF(peer_id, ''), 'Unknown')
)
SELECT name, value, SUM(value) OVER () AS total
FROM grouped
ORDER BY value DESC, name
LIMIT #{limit}

WITH grouped AS (
    SELECT peer_client_name AS name, SUM(ban_count)::bigint AS value
    FROM dashboard_ban_daily_client
    WHERE bucket >= #{startAt} AND bucket < #{endAt}
    GROUP BY peer_client_name
)
SELECT name, value, SUM(value) OVER () AS total
FROM grouped
ORDER BY value DESC, name
LIMIT #{limit}

WITH grouped AS (
    SELECT COALESCE(NULLIF(peer_client_name, ''), 'Unknown') AS name, COUNT(*)::bigint AS value
    FROM ban_history
    WHERE populate_time >= #{startAt} AND populate_time < #{endAt}
    GROUP BY COALESCE(NULLIF(peer_client_name, ''), 'Unknown')
)
SELECT name, value, SUM(value) OVER () AS total
FROM grouped
ORDER BY value DESC, name
LIMIT #{limit}
